module m0 (
  input clk,
  input rst,
  input i0,
  input i1,
  input [0:0] i2,
  output [1:0] o0,
  output [0:0] o1
);
  assign o1 = 4'hc;
  assign o0 = 2'b00;
endmodule

module top (
  input clk,
  input rst,
  input [29:0] i0,
  input [1:0] i1,
  input en0,
  output o0
);
  wire g0;
  assign g0 = clk & en0;
  reg [1:0] r2;
  reg [0:0] r1;
  wire [4:0] w0;
  wire [1:0] w1;
  wire [2:0] w2;
  wire w3;
  assign w3 = 1'b0;
  wire w4;
  wire w5;
  m0 u0 (.clk(clk), .rst(rst), .i0(w1), .i1(1'b0), .i2(i0[18:2] + 17'h14780), .o0(w4), .o1(w5));
  wire [1:0] w6;
  assign w6 = {~w0[4:0], {8'o145, 5'h7}, w5 ? 1'd1 : w2} != (({w5 ? 1'o0 : 1'h0, 5'b10001 ^ w1}) ^ (({rst, w3} & ~7'b0011110) == 'he6 ? en0 : {i1[1:0] | rst, (r2[1] ? 3'd0 : i1), (~8'o0)}) | (w5 == en0 ? r2[1:0] ^ 56 : i1 + w3));
  wire w7;
  assign w7 = {{r1 ? w0 : en0, w1[0] | i1[1:0], i1[1:0] & w1[1:0]}, (w2[2:0] & r1[0:0]) == (w0 ? i0 : 7'h74)};
  assign o0 = {(w1 ~^ i0[29:27]) + {w5, w6[1:1]}, 12'h0, ~w0[4:3]};
  always @(posedge clk) begin
    if (rst) begin
    end else begin
      r1 <= w3 & ((o0 ? i1[0] : 4'b1100) | w7 == w5);
    end
  end
  always @(posedge g0) begin
    if (rst) begin
      r2 <= 2'h0;
    end else begin
    end
  end
endmodule
